"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[94346],{3331:(e,s,i)=>{i.d(s,{R:()=>r,x:()=>l});var t=i(36672);const n={},a=t.createContext(n);function r(e){const s=t.useContext(a);return t.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function l(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),t.createElement(a.Provider,{value:s},e.children)}},48330:(e,s,i)=>{i.r(s),i.d(s,{assets:()=>o,contentTitle:()=>l,default:()=>c,frontMatter:()=>r,metadata:()=>t,toc:()=>u});const t=JSON.parse('{"id":"2023/03/28","title":"2023-03-28","description":"D\xe9bat sur les nouvelles tablo\xefdes et la collecte de donn\xe9es de Windows","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/03/28.md","sourceDirName":"2023/03","slug":"/2023/03/28","permalink":"/fr/2023/03/28","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/03/28.md","tags":[],"version":"current","frontMatter":{"localized_date":"28 mars 2023","top_news":"D\xe9bat sur les nouvelles tablo\xefdes et la collecte de donn\xe9es de Windows"},"sidebar":"defaultSidebar","previous":{"title":"2023-03-29","permalink":"/fr/2023/03/29"},"next":{"title":"2023-03-27","permalink":"/fr/2023/03/27"}}');var n=i(23420),a=i(3331);const r={localized_date:"28 mars 2023",top_news:"D\xe9bat sur les nouvelles tablo\xefdes et la collecte de donn\xe9es de Windows"},l="2023-03-28",o={},u=[{value:"D\xe9bat sur les nouvelles tablo\xefdes et la collecte de donn\xe9es de Windows",id:"d\xe9bat-sur-les-nouvelles-tablo\xefdes-et-la-collecte-de-donn\xe9es-de-windows",level:2},{value:"Les critiques fustigent le trousseau Icloud d&#39;Apple pour ses limites et son exp\xe9rience utilisateur m\xe9diocre",id:"les-critiques-fustigent-le-trousseau-icloud-dapple-pour-ses-limites-et-son-exp\xe9rience-utilisateur-m\xe9diocre",level:2},{value:"La proposition de l&#39;UE en mati\xe8re de surveillance viole la vie priv\xe9e, de meilleures solutions sont n\xe9cessaires",id:"la-proposition-de-lue-en-mati\xe8re-de-surveillance-viole-la-vie-priv\xe9e-de-meilleures-solutions-sont-n\xe9cessaires",level:2},{value:"La Cftc poursuit Binance pour commerce ill\xe9gal et \xe9vasion fiscale",id:"la-cftc-poursuit-binance-pour-commerce-ill\xe9gal-et-\xe9vasion-fiscale",level:2},{value:"L&#39;utilisation par les employ\xe9s de ChatGPT d&#39;OpenAI soul\xe8ve des inqui\xe9tudes en mati\xe8re de s\xe9curit\xe9.",id:"lutilisation-par-les-employ\xe9s-de-chatgpt-dopenai-soul\xe8ve-des-inqui\xe9tudes-en-mati\xe8re-de-s\xe9curit\xe9",level:2},{value:"La technologie de clonage de la voix par l&#39;IA suscite des inqui\xe9tudes quant aux abus et aux escroqueries",id:"la-technologie-de-clonage-de-la-voix-par-lia-suscite-des-inqui\xe9tudes-quant-aux-abus-et-aux-escroqueries",level:2},{value:"L&#39;appareil photo de 40 dollars de John Glenn a r\xe9volutionn\xe9 la photographie spatiale.",id:"lappareil-photo-de-40-dollars-de-john-glenn-a-r\xe9volutionn\xe9-la-photographie-spatiale",level:2},{value:"Les d\xe9veloppeurs discutent des avantages et des inconv\xe9nients du cadre Svelte",id:"les-d\xe9veloppeurs-discutent-des-avantages-et-des-inconv\xe9nients-du-cadre-svelte",level:2},{value:"Safari 16.4 : Fonctionnalit\xe9s et avis mitig\xe9s",id:"safari-164--fonctionnalit\xe9s-et-avis-mitig\xe9s",level:2},{value:"Les utilisateurs de Discussion Service discutent des alternatives \xe0 GitHub pendant les pannes",id:"les-utilisateurs-de-discussion-service-discutent-des-alternatives-\xe0-github-pendant-les-pannes",level:2}];function d(e){const s={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(s.header,{children:(0,n.jsx)(s.h1,{id:"2023-03-28",children:"2023-03-28"})}),"\n",(0,n.jsx)(s.h2,{id:"d\xe9bat-sur-les-nouvelles-tablo\xefdes-et-la-collecte-de-donn\xe9es-de-windows",children:"D\xe9bat sur les nouvelles tablo\xefdes et la collecte de donn\xe9es de Windows"}),"\n",(0,n.jsxs)(s.p,{children:["Les commentaires sur Hacker News discutent de la pratique de Windows qui affiche des nouvelles tablo\xefdes et des notifications push, certains critiquant le syst\xe8me d'exploitation pour avoir d\xe9vi\xe9 de son objectif principal et d'autres soulignant que la fonctionnalit\xe9 vise \xe0 servir les int\xe9r\xeats commerciaux de Microsoft en collectant des donn\xe9es sur les utilisateurs pour la publicit\xe9 cibl\xe9e. Les utilisateurs expriment leurs diff\xe9rentes exp\xe9riences et pr\xe9f\xe9rences avec divers syst\xe8mes d'exploitation, notamment Windows, Ubuntu et macOS, en abordant des questions telles que la stabilit\xe9, la compatibilit\xe9 mat\xe9rielle et la courbe d'apprentissage associ\xe9e aux diff\xe9rents syst\xe8mes d'exploitation. La discussion met en \xe9vidence la nature subjective du choix d'un syst\xe8me d'exploitation, les utilisateurs soulignant l'importance de trouver un syst\xe8me d'exploitation qui corresponde \xe0 leurs besoins et \xe0 leurs pr\xe9f\xe9rences. Les commentateurs font part de leur exp\xe9rience de l'utilisation de pilotes vid\xe9o propri\xe9taires sous Windows et Linux, certains pr\xe9f\xe9rant Windows en raison de la prise en charge du mat\xe9riel et de la facilit\xe9 d'utilisation, tandis que d'autres pr\xe9f\xe8rent Linux pour sa fiabilit\xe9 et le soutien de la communaut\xe9. Les utilisateurs soulignent que la mise \xe0 jour de Windows peut entra\xeener des probl\xe8mes, tels que la rupture du syst\xe8me, la r\xe9duction de l'autonomie de la batterie de l'ordinateur portable et des probl\xe8mes de chargeur de d\xe9marrage, tandis que Linux peut \xeatre instable en raison de bogues au niveau des pilotes et de la gestion des paquets. Les utilisateurs sugg\xe8rent diff\xe9rentes fa\xe7ons de r\xe9soudre ces probl\xe8mes, notamment en utilisant diff\xe9rentes distributions de Linux. La discussion porte sur la compatibilit\xe9 de Linux avec les jeux sur PC, certains affirmant que des am\xe9liorations ont \xe9t\xe9 apport\xe9es ces derni\xe8res ann\xe9es, tandis que d'autres soulignent des lacunes dans la prise en charge et les performances des jeux, notamment en ce qui concerne les mesures anti-triche. Les utilisateurs expriment leur frustration face aux fonctionnalit\xe9s et publicit\xe9s ind\xe9sirables de Windows et discutent des diff\xe9rentes mani\xe8res de personnaliser et de contr\xf4ler leur syst\xe8me d'exploitation ou de passer \xe0 Linux ou \xe0 des consoles de jeu. Le d\xe9bat porte \xe9galement sur le degr\xe9 de compatibilit\xe9 de Linux avec les jeux sur PC, avec des opinions divergentes sur le nombre de jeux qui fonctionnent bien sous Linux et sur l'importance de pouvoir jouer en ligne \xe0 des jeux multijoueurs AAA. Les utilisateurs critiquent Windows pour ses nouvelles tablo\xefdes distrayantes et de mauvaise qualit\xe9, qui causent de la frustration, et discutent des moyens de d\xe9sactiver ou de limiter la quantit\xe9 de titres racoleurs ou trompeurs sur le tableau des widgets. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35323121",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://www.tomshardware.com/news/windows-keeps-feeding-tabloid-news",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"les-critiques-fustigent-le-trousseau-icloud-dapple-pour-ses-limites-et-son-exp\xe9rience-utilisateur-m\xe9diocre",children:"Les critiques fustigent le trousseau Icloud d'Apple pour ses limites et son exp\xe9rience utilisateur m\xe9diocre"}),"\n",(0,n.jsxs)(s.p,{children:["Les utilisateurs critiquent le trousseau iCloud d'Apple pour sa mauvaise exp\xe9rience utilisateur sous Windows et ses limitations sous Mac, comme le fait qu'il soit li\xe9 \xe0 Safari et qu'il soit difficile de trouver les param\xe8tres des mots de passe. L'absence d'int\xe9gration avec le trousseau et les outils de gestion des mots de passe d'Apple sur Windows est signal\xe9e, et Passkeys est consid\xe9r\xe9 comme offrant peu d'am\xe9liorations. Certains utilisateurs sugg\xe8rent que l'absence de gestion rationalis\xe9e des mots de passe fait partie de la strat\xe9gie d'Apple visant \xe0 pousser les clients \xe0 utiliser son propre gestionnaire de mots de passe dans Google Chrome. Apple aurait peut-\xeatre int\xe9r\xeat \xe0 mettre plus de poids dans une bo\xeete \xe0 outils multiplateforme pour soutenir la croissance de ses services. Dans l'ensemble, l'article pr\xe9sente une \xe9valuation mitig\xe9e du syst\xe8me de gestion des mots de passe d'Apple et de sa compatibilit\xe9 avec d'autres navigateurs. Les utilisateurs recommandent d'autres gestionnaires de mots de passe tels que Bitwarden ou 1Password, qui offrent des fonctionnalit\xe9s plus robustes, notamment la possibilit\xe9 de partager les mots de passe entre les membres d'une m\xeame famille. Les utilisateurs soulignent l'importance d'une bonne hygi\xe8ne des mots de passe et mettent en avant les avantages en termes de commodit\xe9 et de s\xe9curit\xe9 de l'utilisation d'un gestionnaire de mots de passe. Certains utilisateurs sugg\xe8rent qu'Apple lance une application autonome pour les mots de passe, accessible \xe0 partir d'une ic\xf4ne de barre d'outils dans Safari et dot\xe9e d'une interface utilisateur compl\xe8te. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35329950",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://cabel.com/2023/03/27/apple-passwords-deserve-an-app/",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"la-proposition-de-lue-en-mati\xe8re-de-surveillance-viole-la-vie-priv\xe9e-de-meilleures-solutions-sont-n\xe9cessaires",children:"La proposition de l'UE en mati\xe8re de surveillance viole la vie priv\xe9e, de meilleures solutions sont n\xe9cessaires"}),"\n",(0,n.jsxs)(s.p,{children:["La proposition d'un fournisseur su\xe9dois de VPN qui obligerait les hommes politiques des pays de l'UE \xe0 se soumettre \xe0 une surveillance audio et vid\xe9o continue, 24 heures sur 24 et 7 jours sur 7, n'est pas adapt\xe9e \xe0 une soci\xe9t\xe9 d\xe9mocratique et viole le droit \xe0 la vie priv\xe9e des individus. L'UE devrait envisager des mesures alternatives pour accro\xeetre la transparence et la responsabilit\xe9, telles que la r\xe9forme du lobbying et l'\xe9largissement de l'acc\xe8s \xe0 l'information, au lieu de mettre en \u0153uvre des mesures de surveillance extr\xeames. La discussion porte sur le manque de confiance dans les hommes politiques et sur la n\xe9cessit\xe9 d'une plus grande transparence dans leur prise de d\xe9cision, avec des suggestions allant de l'examen personnel \xe0 la mise en \u0153uvre de syst\xe8mes similaires aux r\xe9visions de code. L'article traite des processus gouvernementaux d\xe9faillants en termes de traitement de l'information et propose des solutions telles qu'une plus grande transparence, une surveillance intensive des hommes politiques et un ostracisme \xe0 l'ath\xe9nienne par le biais d'un vote public. La proposition de l'UE d'interdire le cryptage de bout en bout et d'exiger des entreprises qu'elles analysent tous les contenus \xe0 la recherche de mat\xe9riel ill\xe9gal porte atteinte \xe0 la vie priv\xe9e et \xe0 la libert\xe9 d'expression, selon les critiques. Le concept de \"porte au visage\" est abord\xe9 en relation avec les n\xe9gociations politiques et le potentiel des propositions politiques extr\xe9mistes pour faire passer des propositions plus mod\xe9r\xe9es pour acceptables. Certains s'inqui\xe8tent du d\xe9ficit d\xe9mocratique de l'UE, de la nature autocratique de la Commission europ\xe9enne et de la dilution de la d\xe9mocratie lorsque l'\xe9lectorat devient trop large et trop diversifi\xe9. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35321994",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://mullvad.net/en/chatcontrol",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"la-cftc-poursuit-binance-pour-commerce-ill\xe9gal-et-\xe9vasion-fiscale",children:"La Cftc poursuit Binance pour commerce ill\xe9gal et \xe9vasion fiscale"}),"\n",(0,n.jsxs)(s.p,{children:["La Commodity Futures Trading Commission (CFTC) am\xe9ricaine a poursuivi Binance pour avoir permis \xe0 des clients am\xe9ricains de n\xe9gocier des actifs num\xe9riques sans s'enregistrer aupr\xe8s de l'agence, ainsi que pour commerce ill\xe9gal et \xe9vasion d'entreprise. Binance aurait utilis\xe9 une structure d'entreprise complexe appel\xe9e \"Tai Chi\" pour \xe9chapper \xe0 la surveillance des autorit\xe9s am\xe9ricaines. Le PDG de Binance nie ces all\xe9gations. Les commentateurs expriment leur scepticisme quant aux actions de la CFTC, et certains critiquent le manque de conformit\xe9 de l'entreprise avec les lois contre le blanchiment d'argent. L'affaire soul\xe8ve des questions sur les motivations des r\xe9gulateurs, et c'est pourquoi la plupart des r\xe9ponses sur Hacker News sont sceptiques \xe0 l'\xe9gard des actions de la CFTC. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35327996",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://www.docdroid.net/60YAbCz/cftc-binance-pdf",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"lutilisation-par-les-employ\xe9s-de-chatgpt-dopenai-soul\xe8ve-des-inqui\xe9tudes-en-mati\xe8re-de-s\xe9curit\xe9",children:"L'utilisation par les employ\xe9s de ChatGPT d'OpenAI soul\xe8ve des inqui\xe9tudes en mati\xe8re de s\xe9curit\xe9."}),"\n",(0,n.jsxs)(s.p,{children:["Les employ\xe9s utilisent le ChatGPT d'OpenAI malgr\xe9 les inqui\xe9tudes concernant la s\xe9curit\xe9 des donn\xe9es, et certaines entreprises en limitent l'utilisation alors que d'autres ne le font pas. Certains craignent que l'outil d'IA ne devienne une cible pour les exploits, et l'\xe9quilibre entre la productivit\xe9 et le risque doit \xeatre pris en compte. Les fuites de donn\xe9es et les risques d'atteinte \xe0 la vie priv\xe9e sont des pr\xe9occupations li\xe9es \xe0 l'utilisation de ChatGPT pour les informations d'entreprise et les informations sensibles, certains sugg\xe9rant la n\xe9cessit\xe9 d'une version priv\xe9e. L'interdiction des smartphones dans les zones s\xe9curis\xe9es et les risques potentiels li\xe9s \xe0 l'utilisation d'outils d'intelligence artificielle tels que ChatGPT sont abord\xe9s, et la n\xe9cessit\xe9 de faire preuve de prudence et de prendre des mesures de protection des donn\xe9es est reconnue. Les entreprises commencent \xe0 d\xe9conseiller aux employ\xe9s d'utiliser des services d'IA g\xe9n\xe9rative et sugg\xe8rent des accords de confidentialit\xe9 et des politiques visant \xe0 pr\xe9venir l'exposition des donn\xe9es. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35330438",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://www.darkreading.com/risk/employees-feeding-sensitive-business-data-chatgpt-raising-security-fears",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"la-technologie-de-clonage-de-la-voix-par-lia-suscite-des-inqui\xe9tudes-quant-aux-abus-et-aux-escroqueries",children:"La technologie de clonage de la voix par l'IA suscite des inqui\xe9tudes quant aux abus et aux escroqueries"}),"\n",(0,n.jsx)(s.p,{children:"Une technologie de clonage de la voix par l'IA est en cours de d\xe9veloppement. Elle permet de cloner des voix avec seulement quelques secondes d'entr\xe9e audio. Cette technologie a des utilisations l\xe9gitimes, comme la cr\xe9ation de livres audio, mais elle soul\xe8ve des inqui\xe9tudes quant \xe0 son utilisation abusive \xe0 des fins d'escroquerie et d'usurpation d'identit\xe9. Play.ht, une start-up qui propose des services de clonage de voix, a invit\xe9 le public \xe0 essayer gratuitement une version b\xeata de sa technologie. Play.ht affirme avoir mis en place \"de nombreuses mesures d'att\xe9nuation pour accro\xeetre la s\xe9curit\xe9 de ce service\" afin d'\xe9viter les abus. Les utilisateurs ont discut\xe9 des utilisations potentielles et des implications de la technologie, les partisans vantant son potentiel positif et les d\xe9tracteurs s'inqui\xe9tant d'une utilisation abusive. La technologie pourrait n\xe9cessiter une r\xe9glementation afin d'\xe9viter les utilisations ill\xe9gales, notamment la cr\xe9ation de faux sons \xe0 des fins malveillantes. Toutefois, certains affirment que l'interdiction de toutes les utilisations l\xe9gales n'emp\xeachera pas les utilisations ill\xe9gales et que l'\xe9ducation peut \xeatre la cl\xe9 pour lutter contre les escroqueries potentielles."}),"\n",(0,n.jsx)(s.h2,{id:"lappareil-photo-de-40-dollars-de-john-glenn-a-r\xe9volutionn\xe9-la-photographie-spatiale",children:"L'appareil photo de 40 dollars de John Glenn a r\xe9volutionn\xe9 la photographie spatiale."}),"\n",(0,n.jsxs)(s.p,{children:["L'utilisation par John Glenn d'un appareil photo de 40 dollars pendant son orbite autour de la Terre a oblig\xe9 la NASA \xe0 repenser le r\xf4le de la photographie dans les missions spatiales. L'article pr\xe9sente les innovations apport\xe9es par la NASA \xe0 l'appareil photo de Glenn, notamment une poign\xe9e pistolet et un m\xe9canisme de d\xe9clenchement par c\xe2ble. L'importance de la cr\xe9ativit\xe9 et des solutions \xe0 faible co\xfbt dans les domaines technologiques est soulign\xe9e dans la section des commentaires. L'appareil photo de Glenn a jou\xe9 un r\xf4le important dans l'\xe9laboration de l'avenir de l'exploration spatiale et a ouvert la voie \xe0 la photographie spatiale. L'histoire souligne le pouvoir de la narration et l'importance de capturer et de partager des moments m\xe9morables, m\xeame s'ils ne sont pas l'objectif principal d'un projet. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35328368",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://petapixel.com/2023/03/23/how-john-glenns-40-camera-forced-nasa-to-rethink-space-missions/",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"les-d\xe9veloppeurs-discutent-des-avantages-et-des-inconv\xe9nients-du-cadre-svelte",children:"Les d\xe9veloppeurs discutent des avantages et des inconv\xe9nients du cadre Svelte"}),"\n",(0,n.jsxs)(s.p,{children:["Svelte est un cadre web populaire pour la construction d'interfaces utilisateur avec une structure facile \xe0 utiliser, des performances d'application rapides et des machines d'\xe9tat observ\xe9es, mais il y a des d\xe9fis potentiels, y compris une courbe d'apprentissage avec des d\xe9clarations r\xe9actives et un potentiel de bogues \xe0 l'\xe9chelle. Svelte utilise une approche bas\xe9e sur un compilateur qui pourrait conduire \xe0 des gains d'efficacit\xe9 pour les d\xe9veloppeurs avec un minimum de code de rebut et une gestion facile de l'\xe9tat, avec des critiques sur la gestion des d\xe9pendances r\xe9actives complexes. Les commentaires comparent Svelte \xe0 des frameworks alternatifs comme React et Vue, avec des \xe9loges pour une exp\xe9rience de d\xe9veloppement et des fonctionnalit\xe9s plus simples, tout en discutant de l'importance de la simplicit\xe9 et de la clart\xe9 dans le code, d'une documentation fiable et d'un outillage. Les discussions sont centr\xe9es sur la comparaison de diff\xe9rents frameworks JavaScript comme React, Vue et Svelte, avec des compromis \xe0 prendre en compte et il est essentiel de faire un choix \xe9clair\xe9. Les utilisateurs trouvent que Svelte est agr\xe9able \xe0 utiliser et qu'il convient aux petits et grands projets d'entreprise, avec des d\xe9fis potentiels concernant le label $ de Svelte et la gestion des effets non locaux. L'article discute de l'exp\xe9rience de l'auteur qui a utilis\xe9 Svelte pour construire un lecteur RSS personnel, soulignant les avantages du format de composant de Svelte, des magasins int\xe9gr\xe9s et de l'API de distribution d'\xe9v\xe9nements, mais mentionnant \xe9galement les points faibles tels que les d\xe9clarations r\xe9actives ($), les blocs d'attente, et les API de transition et d'animation int\xe9gr\xe9es. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35324430",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://tyhopp.com/notes/thoughts-on-svelte",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"safari-164--fonctionnalit\xe9s-et-avis-mitig\xe9s",children:"Safari 16.4 : Fonctionnalit\xe9s et avis mitig\xe9s"}),"\n",(0,n.jsxs)(s.p,{children:["Safari 16.4 apporte des fonctionnalit\xe9s nouvelles et am\xe9lior\xe9es, mais re\xe7oit des avis mitig\xe9s de la part des utilisateurs, certains louant son efficacit\xe9 et d'autres critiquant son manque de capacit\xe9s avanc\xe9es de blocage des publicit\xe9s et de compatibilit\xe9 avec les sites et les extensions. La mise \xe0 jour inclut des corrections de bugs, la prise en charge de la norme Global Relay d'Apple et des notifications Web Push, ainsi que FaceTime SharePlay et le codec ProRes d'Apple pour l'iPhone 13 Pro et 13 Pro Max. Safari 16.4 ajoute la prise en charge de la partie vid\xe9o de l'API Web Codecs, les notifications push pour les Progressive Web Apps (PWA), et le chargement paresseux des iframes, parmi d'autres am\xe9liorations apport\xe9es aux CSS, aux requ\xeates m\xe9dia et \xe0 l'API Web. Le navigateur apporte \xe9galement des am\xe9liorations \xe0 ses outils de d\xe9veloppement, offrant plus de flexibilit\xe9 pour personnaliser les extensions de blocage de contenu et offrant une meilleure protection de la vie priv\xe9e pour les utilisateurs avec le mode Lockdown. Si certains critiquent l'absence de prise en charge des API Fullscreen et Screen Orientation, d'autres s'inqui\xe8tent de la domination d'un seul moteur de navigateur sur iOS. Dans l'ensemble, Safari 16.4 offre un meilleur support aux d\xe9veloppeurs et une exp\xe9rience de navigation plus s\xfbre aux utilisateurs gr\xe2ce \xe0 ses nombreuses corrections de bugs et mises \xe0 jour. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35329961",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://webkit.org/blog/13966/webkit-features-in-safari-16-4/",children:"Lire le texte original"}),"."]}),"\n",(0,n.jsx)(s.h2,{id:"les-utilisateurs-de-discussion-service-discutent-des-alternatives-\xe0-github-pendant-les-pannes",children:"Les utilisateurs de Discussion Service discutent des alternatives \xe0 GitHub pendant les pannes"}),"\n",(0,n.jsxs)(s.p,{children:["Les utilisateurs discutent des alternatives \xe0 GitHub pendant les pannes, y compris les options auto-h\xe9berg\xe9es comme Gerrit, Gitea et CodeCommit. Des commentaires amusants sont faits sur le fait que Discussion Service est une v\xe9rification de dernier recours, et des blagues sont faites sur le fait d'\xeatre hors ligne pour \xe9viter d'\xeatre pirat\xe9. Les utilisateurs sugg\xe8rent d'ajouter une ic\xf4ne de surveillance du trafic sur la page principale pour indiquer que quelque chose ne va pas avec GitHub, et certains remettent en question l'efficacit\xe9 de la messagerie d'erreur de Git. Des solutions alternatives \xe0 l'utilisation de Git \xe0 distance sont sugg\xe9r\xe9es, telles que le travail par e-mail via les diffs ou la mise en place d'un syst\xe8me de sauvegarde avec des instances Git s\xe9par\xe9es. Certains pensent que les r\xe9centes pannes de GitHub sont li\xe9es aux changements survenus apr\xe8s l'acquisition de Microsoft, mais d'autres reconnaissent les difficult\xe9s li\xe9es \xe0 l'\xe9volution rapide du d\xe9veloppement. Les utilisateurs font face au risque de panne en sauvegardant leur code sur des disques durs, des serveurs d'entreprise ou GitLab, ou en utilisant des alternatives telles que la synchronisation des d\xe9p\xf4ts via SSH local ou distant ou l'utilisation du courrier \xe9lectronique pour communiquer les commits. Une liste de num\xe9ros de t\xe9l\xe9phone internationaux pour s'abonner \xe0 un syst\xe8me de gestion des incidents est fournie, avec des tarifs de donn\xe9es applicables et des utilisateurs acceptant les politiques de confidentialit\xe9 et les conditions de service. ",(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35325709",children:"Discuter sur Discussion Service"})," ou ",(0,n.jsx)(s.a,{href:"https://www.githubstatus.com/incidents/52z0j6phhnjs",children:"Lire le texte original"}),"."]})]})}function c(e={}){const{wrapper:s}={...(0,a.R)(),...e.components};return s?(0,n.jsx)(s,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);